Component(
  dsl: 1, id: "market/product-facts", name: "Product facts", kind: Kind.section,
  description: "Calories and preparation time as small chips.",
  variants: [Variant(id: "default", label: "Default", build:
    Wrap(spacing: Space.sm, runSpacing: Space.sm, children: [
      If(condition: options.product.calories, then: Box(padding: Insets(x: 10, y: 6), radius: Radius.full, background: Color.surfaceAlt, child: Text(child: "${options.product.calories} kcal", size: FontSize.sm))),
      If(condition: options.product.prep_time_minutes, then: Box(padding: Insets(x: 10, y: 6), radius: Radius.full, background: Color.surfaceAlt, child: Text(child: "${options.product.prep_time_minutes} min", size: FontSize.sm)))
    ])
  )], options: [DataOption(name: "product", type: Product, required: true)],
)
